from pathlib import Path
import datetime,hashlib,json
r=Path.cwd();w=r/'.build/round364';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
proof=r/'docs/round363-final-source-match.json';selected=json.loads(proof.read_text());assert selected['passed'] and selected['actual_all_gates_passed']
source={row['path']:row['sha256'] for row in selected['inputs'] if row['path'].startswith('track-a/')}
for rel,h in source.items():assert sha(r/rel)==h,rel
assert (r/'track-a/main.cpp').read_text().count('local_names.intern(endpoint)')==1
prior=r/'.build/round359/diagnostic/report.json';diag=json.loads(prior.read_text());assert diag['passed'];rows=[]
for old in diag['runs']:
 p=r/'.build/round359/diagnostic/outputs'/old['case']/'summary.txt';actual=sha(p);assert actual==old['output_sha256']==old['expected_output_sha256'];hist={};lines=0
 for line in p.read_bytes().splitlines():
  fields=line.split(b' ');assert len(fields)==8;length=len(fields[1]);count=int(fields[2]);assert count>0;hist[length]=hist.get(length,0)+count;lines+=1
 total=sum(hist.values());assert total==old['output_records']==old['totals']['direct']['calls']==old['totals']['cuckoo']['calls']
 eligible=sum(n for length,n in hist.items() if 4<=length<=12);misses=old['totals']['direct']['short_misses'];hits=old['totals']['direct']['first_hits']
 ranges={'0_to_3':sum(n for length,n in hist.items() if length<4),'4_to_8':sum(n for length,n in hist.items() if 4<=length<=8),'9_to_12':sum(n for length,n in hist.items() if 9<=length<=12),'13_to_32':sum(n for length,n in hist.items() if 13<=length<=32),'33_to_65535':sum(n for length,n in hist.items() if 33<=length<=65535),'above_65535':sum(n for length,n in hist.items() if length>65535)};assert sum(ranges.values())==total
 rows.append({'case':old['case'],'validated_output':str(p.relative_to(r)),'output_sha256':actual,'output_lines':lines,'observed_intern_calls':total,'weighted_call_count_by_endpoint_byte_length':hist,'weighted_call_count_by_range':ranges,'eligible_4_to_12_calls':eligible,'eligible_fraction':eligible/total,'original_direct_cache_short_misses_all_lengths':misses,'eligible_cache_hit_count_bounds_not_joint_measurement':{'lower':max(0,eligible-misses),'upper':min(eligible,hits)},'eligible_cache_hit_fraction_bounds_not_joint_measurement':{'lower':max(0,eligible-misses)/total,'upper':min(eligible,hits)/total},'expected_input_hashes_reused_without_raw_input_read':old['inputs_sha256']})
report={'observed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'official_score':False,'scope':'Read-only semantic counts from three ALREADY-VALIDATED359 output summaries, not a new program/profile/model run or raw-input pass. Each output group count is its actual request multiplicity; aggregating those counts by endpoint byte length gives actual total LocalEndpoints::intern call lengths because current A makes one intern call per parsed request. Totals cross-check the completed same-stream359 per-worker cache counters and validated output records. Unique-key lengths are not used as traffic weights.','source_binding':source,'source_anchor':str(proof.relative_to(r)),'source_anchor_sha256':sha(proof),'prior_diagnostic_report':str(prior.relative_to(r)),'prior_diagnostic_report_sha256':sha(prior),'per_call_length_traffic_available':True,'cache_hit_by_length_joint_counts_available':False,'runs':rows,'limits':'Eligibility fraction is measured logical call traffic, NOT a measured speedup or exact eligible-cache-hit count. Hit-length joint counts were not collected in359; bounds only subtract at most all original misses from eligible calls. No branch prediction, load/call cost, native/Intel time, charged-memory, sourceS or officialK gain inferred. No raw requests.log read, generator/oracle, compiler, model, benchmark, image execution, host or board action.'}
out=w/'traffic-review.json';assert not out.exists();out.write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'path':str(out),'sha256':sha(out),'traffic':[{'case':row['case'],'eligible_calls':row['eligible_4_to_12_calls'],'total_calls':row['observed_intern_calls'],'eligible_pct':100*row['eligible_fraction'],'eligible_hit_fraction_bounds':row['eligible_cache_hit_fraction_bounds_not_joint_measurement'],'ranges':row['weighted_call_count_by_range']} for row in rows]},indent=2))
